function process() {
  const v=document.getElementById('inp').value.split(/[,\s]+/).map(Number);
  if(v.length<3||v.some(isNaN)){document.getElementById('out').textContent='Format: principal, rate%, years';return;}
  const a=v[0]*Math.pow(1+v[1]/100,v[2]);
  document.getElementById('out').innerHTML='<div class="text-xl font-bold text-brand-400">$'+a.toFixed(2)+'</div><div class="text-xs text-surface-400 mt-1">After '+v[2]+' years at '+v[1]+'%</div>';
}

function process() {
  const v=document.getElementById('inp').value.split(/[,\s]+/).map(Number);
  if(v.length<3||v.some(isNaN)){document.getElementById('out').textContent='Format: amount, rate%, months';return;}
  const mr=v[1]/1200,pmt=v[0]*mr*Math.pow(1+mr,v[2])/(Math.pow(1+mr,v[2])-1);
  document.getElementById('out').innerHTML='<div class="text-xl font-bold text-brand-400">$'+pmt.toFixed(2)+'</div><div class="text-xs text-surface-400 mt-1">Monthly payment</div><div class="text-sm mt-1">Total: $'+(pmt*v[2]).toFixed(2)+'</div>';
}

const R={USD:1,EUR:0.92,GBP:0.79,JPY:149.5,CNY:7.24,CAD:1.36,AUD:1.53,INR:83.1};
function process() {
  const v=document.getElementById('inp').value.trim().split(/\s+/);
  if(v.length<2){document.getElementById('out').textContent='Format: amount FROM TO (e.g. 100 USD EUR)';return;}
  const amt=parseFloat(v[0]),from=v[1].toUpperCase(),to=(v[2]||'USD').toUpperCase();
  if(isNaN(amt)||!R[from]||!R[to]){document.getElementById('out').textContent='Invalid. Try: 100 USD EUR';return;}
  document.getElementById('out').innerHTML='<span class="text-xl font-bold text-brand-400">'+(amt*R[to]/R[from]).toFixed(2)+'</span> <span class="text-surface-400">'+to+'</span>';
}

function process() {
  const v=document.getElementById('inp').value.split(/[,\s]+/).map(Number);
  if(v.length<2||v.some(isNaN)){document.getElementById('out').textContent='Format: price, discount%';return;}
  const s=v[0]*v[1]/100,f=v[0]-s;
  document.getElementById('out').innerHTML='<div class="text-xl font-bold text-brand-400">$'+f.toFixed(2)+'</div><div class="text-xs text-surface-400 mt-1">You save: $'+s.toFixed(2)+' ('+v[1]+'% off)</div>';
}

function process() {
  const v=document.getElementById('inp').value.split(/[,\s]+/);
  if(v.length<2){document.getElementById('out').textContent='Format: price tax% (e.g. 100 8.875)';return;}
  const p=parseFloat(v[0]),t=parseFloat(v[1]);
  if(isNaN(p)||isNaN(t)){document.getElementById('out').textContent='Invalid';return;}
  document.getElementById('out').innerHTML='<div class="text-xl font-bold text-brand-400">$'+(p*(1+t/100)).toFixed(2)+'</div><div class="text-xs text-surface-400 mt-1">Total with '+t+'% tax</div>';
}

function process() {
  const v=document.getElementById('inp').value.split(/[,\s]+/).map(Number);
  if(v.length<3||v.some(isNaN)){document.getElementById('out').textContent='Format: goal, current, monthly (e.g. 10000 1000 500)';return;}
  let bal=v[1],m=0;
  while(bal<v[0]&&m<1200){bal=bal*1.0001+v[2];m++;}
  const y=Math.floor(m/12),rm=m%12;
  document.getElementById('out').innerHTML='<div class="text-xl font-bold text-brand-400">'+(m<1200?y+'y '+rm+'m':'10+ years')+'</div><div class="text-xs text-surface-400 mt-1">To reach $'+v[0].toLocaleString()+'</div>';
}

function process() {
