function process() {
  const v=document.getElementById('inp').value.split(/[,\s]+/).map(Number);
  if(v.length<2||v.some(isNaN)){document.getElementById('out').textContent='Format: distance, time_minutes';return;}
  const p=v[1]/v[0],m=Math.floor(p),s=Math.round((p-m)*60);
  document.getElementById('out').innerHTML='<div class="text-xl font-bold text-brand-400">'+m+':'+String(s).padStart(2,'0')+'</div><div class="text-xs text-surface-400 mt-1">per unit</div>';
