function process() {
  const d=document.getElementById('inp').value;
  if(!d){document.getElementById('out').textContent='Enter date (YYYY-MM-DD)';return;}
  const due=new Date(d);due.setDate(due.getDate()+280);
  const diff=Math.floor((new Date()-new Date(d))/86400000),w=Math.floor(diff/7),dd=diff%7;
  document.getElementById('out').innerHTML='<div class="text-lg font-bold text-brand-400">Due: '+due.toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'})+'</div><div class="text-sm mt-1">'+w+'w '+dd+'d pregnant ('+(40-w)+'w to go)</div>';
}

function process() {
  const v=document.getElementById('inp').value.split(/[,\s]+/).map(Number);
  if(v.length<3||v.some(isNaN)){document.getElementById('out').textContent='Format: drinks, weight_kg, hours, gender(0=male,1=female)';return;}
  const r=(v[3]||0)?0.55:0.68,bac=Math.max(0,(v[0]*14)/(v[1]*1000*r)*100-v[2]*0.015);
  document.getElementById('out').innerHTML='<div class="text-2xl font-bold '+(bac>0.08?'text-red-400':'text-brand-400')+'">'+bac.toFixed(3)+'%</div><div class="text-sm mt-1">'+(bac<0.03?'Safe':bac<0.08?'Impaired':bac<0.15?'Legally drunk':'Severe')+'</div>';
}

function process() {
