function isPrime(n){if(n<2)return!1;if(n===2)return!0;if(n%2===0)return!1;for(let i=3;i*i<=n;i+=2)if(n%i===0)return!1;return!0}
function process(){
  const n=parseInt(document.getElementById('inp').value);
  if(isNaN(n)||n<1){document.getElementById('out').textContent='Enter a number';return;}
  const p=isPrime(n);let nx=n+1;while(!isPrime(nx))nx++;let pv=n-1;while(pv>1&&!isPrime(pv))pv--;
  document.getElementById('out').innerHTML='<div class="text-xl font-bold '+(p?'text-green-400':'text-red-400')+'">'+n+' is '+(p?'PRIME':'NOT prime')+'</div><div class="text-sm mt-1">Next: '+nx+(pv>1?' | Prev: '+pv:'')+'</div>';
}
